def wind_chill(v, t):
    if v < 4.81:
        return int(t) + 10

    temp_c = (33 * ((9/5)*v)**(7/16)) - t
    result = round(temp_c / 2)

    # Ensure rounding to the next integer as per requirement interpretation for negative results or specific cases
    if result < int(result):
        return int(result) + 1

    return int(round(result))

